/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/atendimento.defs.ts" enhancement="_blank"/>

export interface MesaLoad {
  id: string;
  code: string;
  details: {
    readonly disponivel: boolean;
  };
}

export interface ComandaLoad {
  id: string;
  number: number;
  mesaId: string;
  status: 'open' | 'closed';
}

export interface ItemCardapioLoad {
  id: string;
  name: string;
  details: {
    precoVigente: string;
  };
}

export interface ComandaLoadComanda {
  id: string;
  number: number;
  mesaId: string;
  status: 'open' | 'closed';
  details: {
    readonly subtotal: string;
  };
}

export interface MesaLoadComanda {
  id: string;
  code: string;
}

export interface ItemComandaLoadComanda {
  id: string;
  readonly version: number;
  comandaId: string;
  itemCardapioId: string;
  status: 'launched' | 'canceled';
  details: {
    quantidade: number;
    observacao: string;
    precoUnitario: string;
    readonly valorTotal: string;
  };
}

export interface ItemCardapioLoadComanda {
  id: string;
  name: string;
}

export interface ComandaAbrirComanda {
  id: string;
}

export interface ItemComandaLancarItem {
  id: string;
  readonly version: number;
  itemCardapioId: string;
  details: {
    quantidade: number;
    observacao: string;
  };
}

export interface ItemComandaCancelarItem {
  id: string;
  readonly version: number;
}

export interface AtendimentoContracts {
  'comandaRestaurante.atendimento.load': {
    kind: 'qry';
    input: { page?: number; pageSize?: number };
    output: { atendimento: MesaLoad[]; fechamento: ComandaLoad[]; cardapio: ItemCardapioLoad[]; pageLookupAtendimento: number; pageSizeLookupAtendimento: number; hasMoreLookupAtendimento: boolean };
    meta: { output: { atendimento: { entity: 'Mesa'; many: true }; fechamento: { entity: 'Comanda'; many: true }; cardapio: { entity: 'ItemCardapio'; many: true } }; lists: { lookupAtendimento: { key: 'atendimento'; page: 'pageLookupAtendimento'; pageSize: 'pageSizeLookupAtendimento'; hasMore: 'hasMoreLookupAtendimento' } }; params: { page: { pages: 'lookupAtendimento' }; pageSize: { pages: 'lookupAtendimento' } } };
    rules: ['mesaDisponivelParaAbrirComanda'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  'comandaRestaurante.atendimento.loadAtendimento': {
    kind: 'qry';
    input: { page?: number; pageSize?: number };
    output: { atendimento: MesaLoad[]; pageLookupAtendimento: number; pageSizeLookupAtendimento: number; hasMoreLookupAtendimento: boolean };
    meta: { output: { atendimento: { entity: 'Mesa'; many: true } }; lists: { lookupAtendimento: { key: 'atendimento'; page: 'pageLookupAtendimento'; pageSize: 'pageSizeLookupAtendimento'; hasMore: 'hasMoreLookupAtendimento' } }; params: { page: { pages: 'lookupAtendimento' }; pageSize: { pages: 'lookupAtendimento' } } };
    rules: ['mesaDisponivelParaAbrirComanda'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  'comandaRestaurante.atendimento.loadComanda': {
    kind: 'qry';
    input: { id?: string };
    output: { comanda: ComandaLoadComanda };
    meta: { output: { comanda: { entity: 'Comanda'; many: false } }; lists: {}; params: { id: { filters: 'comanda'; field: 'id' } } };
    rules: ['itensSomenteEmComandaAberta', 'itemComandaOperacaoSomenteComandaAberta'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  'comandaRestaurante.atendimento.abrirComanda': {
    kind: 'cmd';
    writes: 'Comanda.create';
    input: { mesaId: string };
    output: { comanda: ComandaAbrirComanda; itemComanda: ItemComandaLoadComanda; mesa: MesaLoad };
    meta: { output: { comanda: { entity: 'Comanda'; many: false }; itemComanda: { entity: 'ItemComanda'; many: false }; mesa: { entity: 'Mesa'; many: false } }; lists: {}; params: {} };
    rules: ['mesaDisponivelParaAbrirComanda', 'umaComandaAbertaPorMesa'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  'comandaRestaurante.atendimento.lancarItem': {
    kind: 'cmd';
    writes: 'ItemComanda.create';
    input: { itemCardapioId: string; details: { quantidade: number; observacao: string }; comandaId: string };
    output: { itemComanda: ItemComandaLancarItem; comanda: ComandaLoad };
    meta: { output: { itemComanda: { entity: 'ItemComanda'; many: false }; comanda: { entity: 'Comanda'; many: false } }; lists: {}; params: {} };
    rules: ['itemComandaOperacaoSomenteComandaAberta'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
  'comandaRestaurante.atendimento.cancelarItem': {
    kind: 'cmd';
    writes: 'ItemComanda.cancelarItemComanda';
    input: { id: string; version: number };
    output: { itemComanda: ItemComandaCancelarItem; comanda: ComandaLoad };
    meta: { output: { itemComanda: { entity: 'ItemComanda'; many: false }; comanda: { entity: 'Comanda'; many: false } }; lists: {}; params: {} };
    rules: ['itemComandaOperacaoSomenteComandaAberta'];
    access: { actors: ['garcom']; grants: ['garcomAtendimentoComandas']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/cardapio.defs.ts" enhancement="_blank"/>

export interface ItemCardapioLoad {
  id: string;
  readonly version: number;
  name: string;
  details: {
    precoVigente: string;
  };
}

export interface CardapioContracts {
  'comandaRestaurante.cardapio.load': {
    kind: 'qry';
    input: { page?: number; pageSize?: number };
    output: { cardapio: ItemCardapioLoad[]; pageListaItensCardapio: number; pageSizeListaItensCardapio: number; hasMoreListaItensCardapio: boolean };
    meta: { output: { cardapio: { entity: 'ItemCardapio'; many: true } }; lists: { listaItensCardapio: { key: 'cardapio'; page: 'pageListaItensCardapio'; pageSize: 'pageSizeListaItensCardapio'; hasMore: 'hasMoreListaItensCardapio' } }; params: { page: { pages: 'listaItensCardapio' }; pageSize: { pages: 'listaItensCardapio' } } };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.cardapio.loadCardapio': {
    kind: 'qry';
    input: { page?: number; pageSize?: number };
    output: { cardapio: ItemCardapioLoad[]; pageListaItensCardapio: number; pageSizeListaItensCardapio: number; hasMoreListaItensCardapio: boolean };
    meta: { output: { cardapio: { entity: 'ItemCardapio'; many: true } }; lists: { listaItensCardapio: { key: 'cardapio'; page: 'pageListaItensCardapio'; pageSize: 'pageSizeListaItensCardapio'; hasMore: 'hasMoreListaItensCardapio' } }; params: { page: { pages: 'listaItensCardapio' }; pageSize: { pages: 'listaItensCardapio' } } };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.cardapio.cadastrarItemCardapio': {
    kind: 'cmd';
    writes: 'ItemCardapio.create';
    input: { name: string; details: { precoVigente: string } };
    output: { itemCardapio: ItemCardapioLoad };
    meta: { output: { itemCardapio: { entity: 'ItemCardapio'; many: false } }; lists: {}; params: {} };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.cardapio.atualizarItemCardapio': {
    kind: 'cmd';
    writes: 'ItemCardapio.update';
    input: { name: string; details: { precoVigente: string }; id: string; version: number };
    output: { itemCardapio: ItemCardapioLoad };
    meta: { output: { itemCardapio: { entity: 'ItemCardapio'; many: false } }; lists: {}; params: {} };
    rules: [];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/fechamento.defs.ts" enhancement="_blank"/>

export interface ComandaLoad {
  id: string;
  readonly version: number;
  number: number;
  status: 'open' | 'closed';
  mesaId: string;
  details: {
    readonly totalComanda: string;
    readonly subtotal: string;
    discountAmount: string;
    paymentMethod: 'cash' | 'debitCard' | 'creditCard' | 'pix';
  };
}

export interface MesaLoad {
  id: string;
  code: string;
  details: {
    readonly disponivel: boolean;
  };
}

export interface ComandaLoadComanda {
  id: string;
  readonly version: number;
  number: number;
  status: 'open' | 'closed';
  details: {
    readonly subtotal: string;
    readonly totalComanda: string;
  };
}

export interface ItemComandaLoadComanda {
  id: string;
  status: 'launched' | 'canceled';
  itemCardapioId: string;
  details: {
    quantidade: number;
    observacao: string;
    precoUnitario: string;
    readonly valorTotal: string;
  };
}

export interface ItemCardapioLoadComanda {
  id: string;
  name: string;
}

export interface ComandaFecharComandaPaga {
  id: string;
  readonly version: number;
  details: {
    discountAmount: string;
    paymentMethod: 'cash' | 'debitCard' | 'creditCard' | 'pix';
  };
}

export interface FechamentoContracts {
  'comandaRestaurante.fechamento.load': {
    kind: 'qry';
    input: { mesaId?: string; page?: number; pageSize?: number };
    output: { fechamento: ComandaLoad[]; atendimento: MesaLoad[]; pageOpenComandaList: number; pageSizeOpenComandaList: number; hasMoreOpenComandaList: boolean };
    meta: { output: { fechamento: { entity: 'Comanda'; many: true }; atendimento: { entity: 'Mesa'; many: true } }; lists: { openComandaList: { key: 'fechamento'; page: 'pageOpenComandaList'; pageSize: 'pageSizeOpenComandaList'; hasMore: 'hasMoreOpenComandaList' } }; params: { mesaId: { filters: 'fechamento'; field: 'mesaId' }; page: { pages: 'openComandaList' }; pageSize: { pages: 'openComandaList' } } };
    rules: ['umaComandaAbertaPorMesa', 'descontoNaoExcedeSubtotal', 'fechamentoLiberaMesa'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.fechamento.loadFechamento': {
    kind: 'qry';
    input: { mesaId?: string; page?: number; pageSize?: number };
    output: { fechamento: ComandaLoad[]; pageOpenComandaList: number; pageSizeOpenComandaList: number; hasMoreOpenComandaList: boolean };
    meta: { output: { fechamento: { entity: 'Comanda'; many: true } }; lists: { openComandaList: { key: 'fechamento'; page: 'pageOpenComandaList'; pageSize: 'pageSizeOpenComandaList'; hasMore: 'hasMoreOpenComandaList' } }; params: { mesaId: { filters: 'fechamento'; field: 'mesaId' }; page: { pages: 'openComandaList' }; pageSize: { pages: 'openComandaList' } } };
    rules: ['umaComandaAbertaPorMesa', 'descontoNaoExcedeSubtotal'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.fechamento.loadComanda': {
    kind: 'qry';
    input: { id?: string };
    output: { comanda: ComandaLoadComanda };
    meta: { output: { comanda: { entity: 'Comanda'; many: false } }; lists: {}; params: { id: { filters: 'comanda'; field: 'id' } } };
    rules: ['itensSomenteEmComandaAberta', 'pagamentoObrigatorioNoFechamento', 'descontoNaoExcedeSubtotal'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
  'comandaRestaurante.fechamento.fecharComandaPaga': {
    kind: 'cmd';
    writes: 'Comanda.fecharComanda';
    input: { details: { discountAmount: string; paymentMethod: 'cash' | 'debitCard' | 'creditCard' | 'pix' }; id: string; version: number };
    output: { comanda: ComandaFecharComandaPaga; itemComanda: ItemComandaLoadComanda; mesa: MesaLoad };
    meta: { output: { comanda: { entity: 'Comanda'; many: false }; itemComanda: { entity: 'ItemComanda'; many: false }; mesa: { entity: 'Mesa'; many: false } }; lists: {}; params: {} };
    rules: ['pagamentoObrigatorioNoFechamento', 'descontoNaoExcedeSubtotal', 'fechamentoLiberaMesa'];
    access: { actors: ['caixa']; grants: ['caixaFechamentoEcadastroOperacional']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/comandaRestaurante/web/contracts/inicio.defs.ts" enhancement="_blank"/>

